/* ==========================================================================
   SINGLE PAGE/POST
   ========================================================================== */

#main {
  @include container;
  @include clearfix;
  margin-top: 1em;
  padding-left: 1em;
  padding-right: 1em;
  animation: intro 0.3s both;
  animation-delay: 0.35s;

  @include breakpoint($x-large) {
    max-width: $x-large;
  }
}

.page {
  @include breakpoint($large) {
    @include span(10 of 12 last);
    @include prefix(0.5 of 12);
    @include suffix(0 of 12);
  }

  .page__inner-wrap {
    @include full();

    .page__content,
    .page__meta,
    .page__share {
      @include full();
    }
  }
}

.page__title {
  margin-top: 0;
  line-height: 1;

  & + .page__meta {
    margin-top: -0.5em;
  }
}

.page__lead {
  font-family: $global-font-family;
  font-size: $type-size-4;
}

.page__content {
  #about-me{
    margin-top: -10em;
      &:before { 
        content: ''; 
        display: block; 
        position: relative; 
        width: 0; 
        height: 10em; 
        margin-top: -10em;
    }
  }
  h1 {
    margin-top: 1em;
    padding-bottom: 0.5em;
    border-bottom: 1px solid $border-color;
  }

  p, li, dl {
    font-size: 1em;
  }

  /* paragraph indents */
  p {
    margin: 0 0 $indent-var;

    /* sibling indentation*/
    @if $paragraph-indent == true {
      & + p {
        text-indent: $indent-var;
        margin-top: -($indent-var);
      }
    }
  }

  a {
    text-decoration: underline;

    &:hover {
      text-decoration: underline;

      img {
        box-shadow: 0 0 10px rgba(#000, 0.25);
      }
    }
  }

  dt {
    margin-top: 1em;
    font-family: $sans-serif;
    font-weight: bold;
  }

  dd {
    margin-left: 1em;
    font-family: $sans-serif;
    font-size: $type-size-6;
  }

  .small {
    font-size: $type-size-6;
  }

  .section-icon {
    margin-right: 0.35rem;
    color: #d84315;
  }

  .section-icon--small {
    color: #e66a2c;
    font-size: 0.85em;
  }

  .inline-icon {
    width: 1.25em;
    margin-right: 0.25rem;
    color: #d96a34;
    text-align: center;
  }

  .portfolio-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1rem;
    margin: 0 0 1.5rem;
  }

  .portfolio-card {
    padding: 1rem 1rem 0.9rem;
    border: 1px solid $border-color;
    border-radius: 8px;
    background: #fff;
  }

  .portfolio-card__top {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem 0.75rem;
    align-items: baseline;
    margin-bottom: 0.5rem;
  }

  .portfolio-card__title {
    margin: 0;
    font-size: $type-size-4;
    line-height: 1.25;
  }

  .portfolio-card__tag {
    display: inline-block;
    padding: 0.2rem 0.55rem;
    border: 1px solid $light-gray;
    border-radius: 999px;
    color: mix(#fff, $text-color, 30%);
    font-family: $sans-serif-narrow;
    font-size: $type-size-7;
    letter-spacing: 0;
    white-space: nowrap;
  }

  .portfolio-card__meta {
    margin: 0 0 0.5rem;
    color: mix(#fff, $text-color, 32%);
    font-size: $type-size-6;
  }

  .portfolio-card__desc {
    margin: 0 0 0.75rem;
  }

  .portfolio-card__list {
    margin: 0 0 0.9rem;
    padding-left: 1.2rem;
  }

  .portfolio-card__list li {
    margin-bottom: 0.35rem;
  }

  .portfolio-card__links {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  .portfolio-link {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.3rem 0.65rem;
    border: 1px solid $light-gray;
    border-radius: 999px;
    text-decoration: none;
    font-size: $type-size-6;
  }

  .portfolio-link:hover {
    border-color: $link-color;
    text-decoration: none;
  }

  .portfolio-link .inline-icon {
    width: auto;
    margin-right: 0;
  }

  .highlight-strip {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem;
    margin: 0 0 1.5rem;
  }

  .highlight-strip__item {
    padding: 0.85rem 0.9rem;
    border-left: 3px solid #d84315;
    background: $lighter-gray;
  }

  .highlight-strip__label {
    margin: 0 0 0.2rem;
    color: mix(#fff, $text-color, 35%);
    font-family: $sans-serif-narrow;
    font-size: $type-size-7;
    text-transform: uppercase;
    letter-spacing: 0;
  }

  .highlight-strip__value {
    margin: 0;
    font-size: $type-size-5;
    line-height: 1.45;
  }

  h1 .section-icon {
    color: #d84315;
  }

  h2 .section-icon {
    color: #e66a2c;
  }

  a:hover .inline-icon,
  li:hover .inline-icon {
    color: #bf360c;
  }

  .cv-list {
    margin: 0 0 1.5em;
  }

